class FencedStorageEngine {
  private highestSeenEpoch = 0;

  public applyWrite(epochToken: number, key: string, value: Uint8Array): void {
    if (epochToken < this.highestSeenEpoch) {
      throw new StaleLeaderFencedError(
        'Rejected zombie write from old primary with epoch ' + epochToken +
        ' (current epoch: ' + this.highestSeenEpoch + ')'
      );
    }
    this.highestSeenEpoch = epochToken;
    this.commitToDisk(key, value);
  }
}
